{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values to the net Stage 1 action values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a bonus to the Stage 1 action value of the previously chosen action to capture choice perseveration.",
      "params": [
        {
          "name": "stickiness",
          "bounds": [0, 5]
        }
      ],
      "evidence": "if prev_a1 != -1:\n            q_net[prev_a1] += stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Allows the reward prediction error from Stage 2 to directly update the Stage 1 action values.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[chosen_a1] += lr * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Decays the values of unchosen actions towards zero to handle drifting rewards.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[1 - chosen_a1] *= (1 - decay)\n        for s in range(2):\n            for a in range(2):\n                if not (s == state_idx and a == chosen_a2):\n                    q_stage2_mf[s, a] *= (1 - decay)",
      "expressible_in_slots": true
    }
  ]
}
